		insert into card_to_antisupports values
			(
				(select antisupports from cards where name ilike cardname),
				(select * from insert_or_get_antisupport(antisupport)) 
		insert into card_to_archetypes values
			(
				(select archetypes from cards where name ilike cardname),
				(select * from insert_or_get_archetype(archetype))
insert into antisupports(name) values(input)
			insert into archetypes(name) values(input)
					insert into boosterpack_cards(boosterpackcardsid, name) values(_boosterpackcardsid, _name)
insert into supports(name) values(input)
		insert into card_to_supports values
			(
				(select supports from cards where name ilike cardname),
				(select * from insert_or_get_support(support))
		insert into boosterpack_dates(boosterpackdatesid, name, date) values(boosterpackdatesid, name, date)
	insert into translations(cardid, language, name, lore)
