--
-- Name: delete_antisupport_relation(character varying, character varying); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.delete_antisupport_relation(IN cardname character varying, IN antisupport character varying)
    LANGUAGE plpgsql
    AS $$BEGIN
		
		delete from card_to_antisupports 
		where 
			cardantisupportsid = (select antisupports from cards where name ilike cardname) and
			antisupportsid = (select id from antisupports where name ilike antisupport);
		
	END;
$$;


--
-- Name: delete_archetype_relation(character varying, character varying); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.delete_archetype_relation(IN cardname character varying, IN archetype character varying)
    LANGUAGE plpgsql
    AS $$BEGIN

		delete from card_to_archetypes
		where 
			cardarchetypesid = (select archetypes from cards where name ilike cardname) and 
			archetypesid = (select id from archetypes where name ilike archetype);

	END;
$$;


--
-- Name: delete_support_relation(character varying, character varying); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.delete_support_relation(IN cardname character varying, IN support character varying)
    LANGUAGE plpgsql
    AS $$BEGIN
		
		delete from card_to_supports
		where 
			cardsupportsid = (select supports from cards where name ilike cardname) and 
			supportsid = (select id from supports where name ilike support);
		
	END;
$$;


--
-- Name: get_anime_cards_autocomplete(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_anime_cards_autocomplete(input character varying) RETURNS SETOF character varying
    LANGUAGE plpgsql
    AS $$
declare
    contains    varchar;
    starts_with varchar;
BEGIN

    contains := '%' || input || '%';
    starts_with := input || '%';

    return query
        select name
        from anime_cards
        where name ilike contains
        order by case
                     when name ilike starts_with then 0
                     else 1
                     end,
                 name
        limit 25;

END;
$$;


