--
-- Name: joined_cards; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.joined_cards AS
 SELECT cards.id,
    cards.name,
    cards.realname,
    cards.cardtype,
    cards.property,
    cards.types,
    cards.attribute,
    cards.materials,
    cards.lore,
    cards.pendulumlore,
    cards.archetypes,
    cards.supports,
    cards.antisupports,
    cards.link,
    cards.linkarrows,
    cards.atk,
    cards.def,
    cards.level,
    cards.pendulumscale,
    cards.rank,
    cards.tcgexists,
    cards.ocgexists,
    cards.img,
    cards.url,
    cards.passcode,
    cards.ocgstatus,
    cards.tcgstatus,
    cards.genesys,
    cards.cardtrivia,
    ar.name AS archetypename,
    s.name AS supportname,
    asu.name AS antisupportname,
    tr.id AS translationid,
    tr.cardid,
    tr.language,
    tr.name AS translationname,
    tr.lore AS translationlore
   FROM (((((((public.cards
     LEFT JOIN public.card_to_archetypes ca ON ((ca.cardarchetypesid = cards.archetypes)))
     LEFT JOIN public.archetypes ar ON ((ar.id = ca.archetypesid)))
     LEFT JOIN public.card_to_supports cs ON ((cs.cardsupportsid = cards.supports)))
     LEFT JOIN public.supports s ON ((s.id = cs.supportsid)))
     LEFT JOIN public.card_to_antisupports cas ON ((cas.cardantisupportsid = cards.antisupports)))
     LEFT JOIN public.antisupports asu ON ((asu.id = cas.antisupportsid)))
     LEFT JOIN public.translations tr ON ((tr.cardid = cards.id)));


--
-- Name: get_card_exact(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_card_exact(input character varying) RETURNS SETOF public.joined_cards
    LANGUAGE plpgsql
    AS $$begin
	
	return query
		select * from joined_cards
		where 
			name ilike input or
			realname ilike input
		order by name;

end
$$;


--
-- Name: get_card_fuzzy(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_card_fuzzy(input character varying) RETURNS SETOF public.joined_cards
    LANGUAGE plpgsql
    AS $$BEGIN

    return query
        select *
        from joined_cards
                 inner join
             (
                 select id
                 from cards
                 order by levenshtein(name, input),
                          name
                 limit 1
             ) absurdly_long_name_because_it_doesnt_matter
             using (id);

END;
$$;


