--
-- Name: get_random_card(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_random_card() RETURNS SETOF public.joined_cards
    LANGUAGE plpgsql
    AS $$
BEGIN

    return query
        select * from joined_cards
        inner join
        (
            select id from cards
            tablesample bernoulli(1)
            order by random()
            limit 1
        ) absurdly_long_name_because_it_doesnt_matter
        using (id)
    ;

END;
$$;


--
-- Name: get_random_monster(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_random_monster() RETURNS SETOF public.joined_cards
    LANGUAGE plpgsql
    AS $$
    BEGIN

        return query
            select * from joined_cards
            inner join
            (
                select id from cards
                tablesample bernoulli(1)
                where cards.cardtype = 'Monster'
                order by random()
                limit 1
            ) absurdly_long_name_because_it_doesnt_matter
            using (id)
        ;

    end;
$$;


